const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.book}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'#';}catch{return '#';}};
const skin={c:['C','#e9eddf','#7b8d56'],python:['Py','#f3eadb','#ac8959'],calculus:['∫','#e7edf1','#7e94a0'],linear:['A','#efe9f2','#9c83a5']};
const subject=id=>SUBJECTS.find(s=>s.id===id)||{name:'自定义',en:'YOUR SPACE'};
const style=id=>`--subject-bg:${(skin[id]||skin.c)[1]};--subject-color:${(skin[id]||skin.c)[2]}`;
const symbol=id=>`<span class="subject-symbol" style="${style(id)}">${(skin[id]||['知'])[0]}</span>`;
const tag=id=>`<span class="subject-tag" style="${style(id)}">${esc(subject(id).name)}</span>`;
const navs=[['today','home','今日学习'],['courses','grid','学科课程'],['knowledge','bulb','知识库'],['books','book','我的书架'],['notes','note','学习笔记'],['memory','heart','学习记忆'],['resources','link','资源花园']];
let state=getState(),books=[],resources={items:[],status:'loading'},route='today',course=null,filter='all',query='',knowledgeMode='all',toastTimer,installPrompt,modalReturnFocus;
let timer={duration:25*60,remaining:25*60,end:null};
try{const t=JSON.parse(sessionStorage.getItem('shizhi-timer'));if(t&&Number.isFinite(t.remaining)&&Number.isFinite(t.duration)){timer=t;}}catch{}
const day=()=>todayKey();
const dateText=d=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',timeZone:'Asia/Shanghai'}).format(new Date(d+'T12:00:00+08:00'));
const dateWeek=d=>new Intl.DateTimeFormat('zh-CN',{weekday:'long',timeZone:'Asia/Shanghai'}).format(new Date(d+'T12:00:00+08:00'));
const doneToday=()=>state.dailyDone[day()]||[];
const focused=()=>state.sessions.filter(x=>x.date===day()).reduce((s,x)=>s+x.minutes,0);
const currentDaily=()=>personalizedDailyLessons(LESSONS,state,day());
const memoryUI=createMemoryUI({getState:()=>state,setMemory:(memory,options={})=>{state.memory=memory;if(!options.automatic)state.settings.memoryAutoSync=false;return persist();},setAutoSync:value=>{state.settings.memoryAutoSync=value;return persist();},render:()=>render(),toast,modal,closeModal,confirmDialog,chooseFile,icon,esc,subject,navigate});
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function persist(){try{state=saveState(state);return true;}catch(e){state=getState();toast(e.message);return false;}}
function navigate(target){if(route===target&&!course){render();return;}if(location.hash===`#${target}`)onRoute();else location.hash=target;}
function onRoute(){const next=location.hash.slice(1).split('?')[0];route=[...navs.map(n=>n[0]),'settings','review'].includes(next)?next:'today';course=null;filter='all';query='';knowledgeMode='all';render();window.scrollTo(0,0);}
const art=`<svg class="hero-art" viewBox="0 0 280 260" aria-hidden="true"><ellipse cx="172" cy="232" rx="100" ry="15" fill="#163a30" opacity=".5"/><path d="M181 177c-5-53-2-96 18-137" fill="none" stroke="#b9c78f" stroke-width="2"/><path d="M187 99c-33-4-46-25-44-42 32 2 46 19 44 42Zm4-27c4-32 24-43 40-38-2 27-18 40-40 38Zm-9 57c-32-1-45-18-43-34 27-3 44 14 43 34Zm2-18c10-28 32-33 47-24-8 26-24 32-47 24Z" fill="#a3b782"/><path d="M178 171c-21-23-31-35-53-41m25 22c-22 4-35-7-35-20 18-4 31 4 35 20Z" fill="#809d70" stroke="#809d70"/><g transform="rotate(-8 130 205)"><path d="m76 194 130-9 10 30-131 8Z" fill="#b6c29c"/><path d="m84 201 124-8 5 15-125 9Z" fill="#f1efd8"/><path d="m78 194 10 29-7 1-10-29Z" fill="#829975"/><path d="m84 170 132 4-11 29-135-5Z" fill="#d5d6b4"/><path d="m83 179 128 3-5 14-130-4Z" fill="#f0eed8"/><path d="m78 172 9 1-13 26-8-2Z" fill="#c1c69e"/></g><g transform="rotate(12 190 141)"><path d="m168 98 56 5-8 99-56-5Z" fill="#788e70"/><path d="m173 100 51 5-8 94-50-5Z" fill="#c7c9a6"/><path d="m179 114 31 3m-32 5 31 3m-27 16 17 1" stroke="#7c936f" stroke-width="1"/><path d="m167 98 7 1-8 95-6 3Z" fill="#a5b18c"/></g><path d="M229 204c12-13 23-18 35-17-3 18-17 24-35 17Z" fill="#94aa78"/><circle cx="107" cy="67" r="3" fill="#c9d4a3" opacity=".55"/><path d="M102 103h9m-4-4v9m135 32h9m-5-4v8" stroke="#bdcba0" opacity=".6"/></svg>`;

function shell(body){const active=route==='review'?'knowledge':route;document.querySelector('#app').innerHTML=`<aside class="sidebar"><a href="#today" class="brand"><span class="brand-mark">知</span><div><h1>拾知</h1><p>GROW A LITTLE, DAILY</p></div></a><div class="nav-label">我的学习空间</div><nav aria-label="主导航">${navs.map(([id,i,label])=>`<button class="nav-item ${active===id?'active':''}" data-nav="${id}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${active===id?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item ${active==='settings'?'active':''}" data-nav="settings">${icon('settings')}空间设置</button><div class="sidebar-quote">每一次拾起，<br>都在靠近更好的自己。<span>SMALL STEPS, DEEP ROOTS.</span></div></div></aside><div class="app-shell"><header class="topbar"><a href="#today" class="mobile-brand"><span class="brand-mark">知</span><strong>拾知</strong><span>你的学习空间</span></a><div class="breadcrumb">我的空间 <span>/</span> <strong>${esc(navs.find(n=>n[0]===active)?.[2]||'空间设置')}</strong></div><div class="top-actions"><button class="search-btn" data-action="search" aria-label="搜索知识、课程与笔记">${icon('search')}<span>搜索你的知识</span><kbd>Ctrl K</kbd></button><span class="sync-status"><i class="online-dot"></i>${navigator.onLine?'学习空间已就绪':'离线学习中'}</span><button class="avatar" data-nav="settings" aria-label="打开空间设置">Y</button></div></header><main class="content" id="main" tabindex="-1">${body}<footer class="page-footer"><span>拾知 SHIZHI · 让学习慢慢生长</span><a href="https://github.com/Yang071212/shizhi-study" target="_blank" rel="noopener noreferrer">在 GitHub 一起生长 ↗</a></footer></main></div><nav class="bottom-nav" aria-label="手机导航">${[['today','home','今日'],['courses','grid','学科'],['books','book','书架'],['knowledge','bulb','知识库'],['notes','note','笔记']].map(([id,i,label])=>`<button data-nav="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav>`;bindView();}
function intro(eyebrow,title,description,right=''){return `<section class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${description}</p></div>${right}</section>`;}
function heading(title,en,more=''){return `<div class="section-heading"><h3>${title}<small>${en}</small></h3>${more}</div>`;}
function lessonRow(l,review=false){return `<button class="lesson-row" data-lesson="${l.id}" ${review?'data-review="true"':''}>${symbol(l.subject)}<div class="lesson-info"><h4>${esc(l.title)}</h4><p>${esc(subject(l.subject).name)} · ${l.minutes} 分钟 · ${esc(l.chapter)}</p></div>${tag(l.subject)}<span class="lesson-end ${state.completed[l.id]?'done-check':''}">${icon(state.completed[l.id]?'checkcircle':'chevron')}</span></button>`;}
function bookMini(b){return `<button class="book-mini" data-book="${esc(b.id)}"><span class="book-cover"><span>PDF</span></span><div><h4>${esc(b.name.replace(/\.pdf$/i,''))}</h4><p>${b.totalPages?`第 ${b.page} / ${b.totalPages} 页`:'从第一页开始'} · 继续阅读</p></div></button>`;}
function todayView(){const daily=currentDaily(),due=dueReviews(state,LESSONS),first=due[0]||daily.find(l=>!doneToday().includes(l.id))||daily[0],progress=Math.min(100,focused()/state.settings.goal*100),week=Array.from({length:7},(_,i)=>shiftDay(day(),i-6));return intro('A LITTLE EVERY DAY','今天，也让知识生长。','不必一口气学会所有，每天拾起一点就好。',`<div class="date-chip">${icon('calendar')}<span>${dateText(day())}&nbsp; ${dateWeek(day())}</span></div>`)+`<div class="dashboard-grid"><div class="main-column">${memoryUI.banner()}<section class="hero"><div class="hero-bg-ring"></div><div class="hero-copy"><div class="eyebrow">YOUR DAILY GROWTH</div><h3>保持好奇，<br>让每一小步都有回响。</h3><p>${due.length?`有 ${due.length} 个知识点在等你温习。`:'为你准备了今天的四门微课程。'}<br>从一个概念、一段代码、一页书开始。</p><button class="btn" data-lesson="${first.id}" ${due.length?'data-review="true"':''}>${icon('play')}${due.length?'开始今日复习':'开始今天的学习'} ${icon('arrow')}</button></div>${art}</section><div class="stat-row"><div class="stat-card"><span class="stat-icon">${icon('checkcircle')}</span><div><div class="stat-num">${doneToday().length}<small>个</small></div><div class="stat-name">今日学过的知识点</div></div></div><div class="stat-card"><span class="stat-icon">${icon('flame')}</span><div><div class="stat-num">${streak(state)}<small>天</small></div><div class="stat-name">连续学习</div></div></div><div class="stat-card"><span class="stat-icon">${icon('clock')}</span><div><div class="stat-num" data-focused>${Math.floor(focused())}<small>分钟</small></div><div class="stat-name">今日专注时长</div></div></div></div>${heading('今日学习清单','DAILY PICKS',`<button class="text-btn" data-nav="courses">全部课程 ${icon('chevron')}</button>`)}<div class="today-list">${daily.map(l=>lessonRow(l)).join('')}</div><p class="learning-footnote">${icon('refresh')}${state.memory?'根据学习记忆与自测结果安排 · 可在学习记忆页调整':'按北京时间每日自动换一组 · 每科一节，按自己的节奏选择学习'}</p>${due.length?heading('该温习一下了','RECALL',`<button class="text-btn" data-nav="review">${due.length} 个待复习 ${icon('chevron')}</button>`)+`<div class="today-list" style="margin-bottom:26px">${due.slice(0,2).map(l=>lessonRow(l,true)).join('')}</div>`:''}${heading('在书页之间，继续探索','YOUR BOOKS',`<button class="text-btn" data-nav="books">我的书架 ${icon('chevron')}</button>`)}<div class="shelf-preview">${books.length?books.slice(0,2).map(bookMini).join(''):`<div class="reading-empty">${icon('book')}<div><h4>下一段旅程，从一本书开始</h4><p>导入你的 PDF，留下阅读的足迹。</p></div><button class="text-btn" data-action="upload">导入电子书 ${icon('plus')}</button></div>`}</div></div><aside class="right-column"><section class="panel goal-panel"><div class="small-title">今日小目标<button class="icon-btn" data-nav="settings" aria-label="设置每日目标">${icon('external')}</button></div><div class="goal-ring"><svg viewBox="0 0 140 140" aria-hidden="true"><circle cx="70" cy="70" r="56" stroke="#edf0e4" stroke-width="6" fill="none"/><circle cx="70" cy="70" r="56" stroke="#8fA66c" stroke-width="6" fill="none" stroke-linecap="round" stroke-dasharray="${progress*3.5186} 351.86"/></svg><strong>${Math.floor(focused())}<span> / ${state.settings.goal}</span></strong><span>分钟专注</span></div><p class="goal-caption">${focused()>=state.settings.goal?'今天的努力，已经被好好记下。':'慢慢来，每一份专注都算数。'}</p><div class="goal-days">${week.map(d=>`<div class="goal-day ${d===day()?'current':''} ${(state.dailyDone[d]?.length||state.sessions.some(s=>s.date===d))?'finished':''}"><span>${['日','一','二','三','四','五','六'][new Date(d+'T12:00:00Z').getUTCDay()]}</span><i>${state.dailyDone[d]?.length?'✓':Number(d.slice(-2))}</i></div>`).join('')}</div></section><section class="panel focus-panel"><div class="small-title"><span>留一段时间给自己</span>${icon('leaf')}</div><div class="timer-digits" data-timer>25:00</div><p class="timer-caption">暂时放下别的，只做眼前这一件事。</p><div class="timer-actions"><button class="btn" data-action="timer" data-timer-toggle>${icon('play')}开始专注</button><button class="icon-btn" data-action="timer-reset" aria-label="重置专注计时">${icon('reset')}</button></div></section><section class="panel quote-panel"><div class="quote-glyph">“</div><p>求知的路上，<br>每一个今天都不会白走。</p><span>STAY CURIOUS, KEEP GROWING</span></section></aside></div>`;}
function coursesView(){if(course){const lessons=LESSONS.filter(l=>l.subject===course);return `<button class="back-btn" data-action="back-courses">${icon('back')}返回全部学科</button>`+intro(subject(course).en,esc(subject(course).name),esc(subject(course).description))+`<div class="info-box">先理解一个概念，再看一段示例，最后用一道自测检验。学完后，知识点会自动加入复习队列。</div>`+[...new Set(lessons.map(l=>l.chapter))].map(ch=>`<h3 class="chapter-heading">${esc(ch)}</h3><div class="lesson-grid">${lessons.filter(l=>l.chapter===ch).map(l=>lessonRow(l)).join('')}</div>`).join('');}return intro('EXPLORE YOUR SUBJECTS','每一门，都有自己的风景。','从概念到例题，再到一题自测，把基础慢慢学扎实。')+`<div class="subject-grid">${SUBJECTS.map(s=>{const all=LESSONS.filter(l=>l.subject===s.id),n=all.filter(l=>state.completed[l.id]).length;return `<button class="subject-card" data-subject="${s.id}">${symbol(s.id)}${icon('arrow')}<h3>${esc(s.name)}</h3><div class="subject-en">${esc(s.en)}</div><p>${esc(s.description)}</p><div class="progress-track"><i style="width:${n/all.length*100}%"></i></div><div class="progress-label"><span>${n} / ${all.length} 节已学习</span><span>${Math.round(n/all.length*100)}%</span></div></button>`;}).join('')}</div><div class="feature-list"><div><strong>概念，先讲清楚</strong>用直觉与小例子理解知识点。</div><div><strong>学完，就试一下</strong>每节课附自测和答案解析。</div><div><strong>学过，再次遇见</strong>用间隔复习把知识记得更牢。</div></div>${heading('让知识延伸','KEEP EXPLORING',`<button class="text-btn" data-nav="resources">进入资源花园 ${icon('arrow')}</button>`)}<div class="info-box">内置内容为原创基础复习材料。想看完整教程或做更多练习，可以继续阅读资源花园里的 GitHub 开源项目。</div>`;}
function filterBar(extra=''){return `<div class="toolbar"><div class="tabs" role="group" aria-label="按学科筛选">${[['all','全部'],...SUBJECTS.map(s=>[s.id,s.name]),['custom','自建内容']].map(([id,n])=>`<button class="filter-tab ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${esc(n)}</button>`).join('')}</div>${extra}<label class="search-field">${icon('search')}<input id="page-search" placeholder="搜索知识点、关键词…" aria-label="搜索当前内容" value="${esc(query)}"></label></div>`;}
function knowledgeView(){const dueIds=new Set(dueReviews(state,LESSONS).map(x=>x.id));const ls=LESSONS.filter(l=>(filter==='all'||l.subject===filter)&&(knowledgeMode==='all'||knowledgeMode==='mistakes'&&state.quiz[l.id]?.correct===false||knowledgeMode==='due'&&dueIds.has(l.id))&&`${l.title} ${l.summary} ${l.takeaways.join(' ')}`.toLowerCase().includes(query.toLowerCase()));const ns=state.notes.filter(n=>n.tags.includes('知识点')&&(filter==='all'||filter==='custom'||n.tags.includes(subject(filter).name))&&`${n.title} ${n.body}`.toLowerCase().includes(query.toLowerCase()));return intro('YOUR KNOWLEDGE GARDEN','把零散知识，种成一片森林。','公式、易错点与自己的理解，都在这里慢慢积累。',`<button class="btn" data-action="new-knowledge">${icon('plus')}添加知识点</button>`)+filterBar(`<select id="knowledge-mode" class="filter-tab" aria-label="复习范围"><option value="all" ${knowledgeMode==='all'?'selected':''}>全部知识点</option><option value="mistakes" ${knowledgeMode==='mistakes'?'selected':''}>答错的知识点</option><option value="due" ${knowledgeMode==='due'?'selected':''}>到期复习</option></select>`)+`<p class="count-note">${ls.length} 个课程知识点 · ${ns.length} 个自建知识点 ${knowledgeMode==='due'?'· 按记忆情况安排间隔':''}</p><div class="knowledge-layout">${knowledgeMode==='all'?ns.map(n=>`<button class="knowledge-card" data-note="${esc(n.id)}"><span class="subject-tag">自建知识点</span><h3>${esc(n.title)}</h3><p>${esc(n.body.slice(0,200))}</p><div class="card-foot"><span>${esc(n.tags.filter(t=>t!=='知识点').join(' · ')||'自己的理解')}</span>${icon('chevron')}</div></button>`).join(''):''}${ls.map(l=>`<button class="knowledge-card" data-lesson="${l.id}" ${knowledgeMode==='due'?'data-review="true"':''}>${tag(l.subject)}<h3>${esc(l.title)}</h3><p>${esc(l.takeaways.join(' · '))}</p><div class="card-foot"><span>${state.quiz[l.id]?.correct===false?'需要再巩固':state.completed[l.id]?'已学 · 随时温习':esc(l.chapter)}</span>${icon('arrow')}</div></button>`).join('')}</div>${!ls.length&&(!ns.length||knowledgeMode!=='all')?empty('bulb','留一点空白，让新知长进来。',knowledgeMode==='mistakes'?'目前没有答错记录。完成课程自测后，答错的知识点会出现在这里。':knowledgeMode==='due'?'目前没有到期知识点。学完一节后，次日起会安排温习。':'试试其他关键词，或添加自己的第一条知识点。'):''}`;}
function empty(i,title,desc,button=''){return `<div class="empty-state">${icon(i)}<h3>${title}</h3><p>${desc}</p>${button}</div>`;}
function booksView(){return intro('A SHELF OF POSSIBILITIES','书页之间，自有新的天地。','把电子书装进口袋，接着上一次读到的地方。')+`<section class="upload-zone"><div class="upload-copy">${icon('upload')}<div><h3>给书架添一本新书</h3><p>支持 PDF，单本最大 100 MB · 书籍保存在当前设备</p></div></div><button class="btn" data-action="upload">${icon('plus')}导入 PDF</button></section><div class="toolbar"><span class="count-note" style="margin:0">${books.length} 本电子书 · 阅读进度自动保存</span><button class="text-btn" data-action="backup">${icon('download')}备份书架与学习记录</button></div>${books.length?`<div class="library-grid">${books.map(b=>`<article class="book-card"><button class="book-open" data-book="${esc(b.id)}"><div class="book-cover"><span>MY READING COLLECTION</span>${esc(b.name.replace(/\.pdf$/i,''))}<span>SHIZHI · PDF</span></div><h3>${esc(b.name.replace(/\.pdf$/i,''))}</h3></button><p class="book-meta">${(b.size/1048576).toFixed(1)} MB · ${b.totalPages?`第 ${b.page} / ${b.totalPages} 页`:'等待翻开'}</p><div class="progress-track"><i style="width:${b.totalPages?b.page/b.totalPages*100:0}%"></i></div><div class="book-actions"><button class="btn secondary" data-book="${esc(b.id)}">${icon('book')}继续阅读</button><button class="icon-btn" data-action="delete-book" data-id="${esc(b.id)}" aria-label="移除 ${esc(b.name)}">${icon('trash')}</button></div></article>`).join('')}</div>`:empty('book','你的第一本书，会是什么？','当前还没有导入电子书。点击上方按钮选择手机或电脑中的 PDF，首次阅读后即可离线继续。')}<div class="info-box" style="margin-top:25px">换设备时，在设置中导出完整备份，再到新设备恢复。不同网址、浏览器和设备的本地书架各自独立。清理浏览器数据前，请先备份。</div>`;}
function notesView(){const notes=state.notes.filter(n=>`${n.title} ${n.body} ${n.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));return intro('THOUGHTS WORTH KEEPING','留下，属于自己的理解。','记一道错题、一瞬灵感，或一个终于想通的概念。',`<button class="btn" data-action="new-note">${icon('plus')}写笔记</button>`)+`<div class="toolbar"><span class="count-note" style="margin:0">${state.notes.length} 篇记录，让思考有迹可循</span><label class="search-field">${icon('search')}<input id="page-search" placeholder="搜索笔记、标签…" aria-label="搜索笔记" value="${esc(query)}"></label></div><div class="knowledge-layout">${notes.slice().reverse().map(n=>`<button class="note-card" data-note="${esc(n.id)}"><span class="note-date">${esc(new Date(n.createdAt).toLocaleDateString('zh-CN'))}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="card-foot"><span>${esc(n.tags.map(t=>'#'+t).join(' ')||'随手记')}</span>${icon('arrow')}</div></button>`).join('')}</div>${!notes.length?empty('note','好的想法，值得被记下来。','你可以自由添加任何学科的内容。给笔记加上“知识点”标签，它也会出现在知识库。',`<button class="btn secondary" data-action="new-note">${icon('edit')}写下第一篇笔记</button>`):''}`;}
function resourcesView(){const items=[...(resources.items||[]),...state.customResources.map(r=>({...r,category:'custom',description:r.category,license:'自建资源'}))].filter(r=>(filter==='all'||r.category===filter)&&`${r.title} ${r.description}`.toLowerCase().includes(query.toLowerCase()));return intro('OPEN SOURCE, OPEN POSSIBILITIES','向更大的知识世界，借一点光。','精选 GitHub 学习资源，从入门教程到深入探索。',`<button class="btn" data-action="new-resource">${icon('plus')}添加资源</button>`)+`<div class="info-box">每天自动检查开源项目信息，打开应用时获取最新资源快照。${resources.lastSuccessAt?`上次完整检查：${esc(new Date(resources.lastSuccessAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}（北京时间）`:'资源快照正在准备。'}${resources.status==='partial'||resources.status==='error'?' 部分来源检查未成功，保留上次可用资料。':''} <button class="text-btn" style="display:inline-flex;margin-left:8px" data-action="refresh-resources">${icon('refresh')}检查更新</button></div>`+filterBar()+`<div class="resource-grid">${items.map(r=>`<article class="resource-card"><span class="subject-tag" style="align-self:flex-start">${r.category==='tool'?'应用底座':r.category==='extra'?'拓展学习':r.category==='custom'?'自建资源':esc(subject(r.category).name)}</span><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><div class="resource-foot"><span>${esc(r.license||'参见项目说明')}${r.stars?` · ★ ${r.stars>1000?(r.stars/1000).toFixed(1)+'k':r.stars}`:''}</span><a href="${esc(safeURL(r.url))}" target="_blank" rel="noopener noreferrer">打开 ${icon('external')}</a></div>${r.status==='error'?'<p style="margin:9px 0 0;font-size:9px">本次来源检查失败，展示已保存的信息</p>':''}${r.category==='custom'?`<button class="text-btn" data-action="delete-resource" data-id="${esc(r.id)}">移除资源</button>`:''}</article>`).join('')}</div>${!items.length?empty('link','再换一个角度，继续探索。','当前分类下没有匹配内容。'):''}`;}
function reviewView(){const due=dueReviews(state,LESSONS);return intro('REVISIT & REMEMBER','记住，需要再相逢。','读完只是开始，用回忆让知识真正留下。')+`<div class="info-box">每次学完会安排次日复习；之后按“还不熟 / 记住了 / 很轻松”调整间隔。答错题目也会提前安排到次日。</div><div class="lesson-grid">${due.map(l=>lessonRow(l,true)).join('')}</div>${due.length?'':empty('checkcircle','今天的复习，已经完成。','去学一点新内容，或随手翻开一本书吧。',`<button class="btn secondary" data-nav="courses">浏览学科课程 ${icon('arrow')}</button>`)}`;}
function settingsView(){return intro('MAKE ROOM FOR YOURSELF','让学习空间，更合你的心意。','目标、备份与扩展，为长久的学习留一点余地。')+`<div class="settings-layout"><section class="panel"><div class="small-title">让学习记忆接上进度 ${icon('heart')}</div><div class="setting-row"><div><h4>学习记忆与课程安排</h4><p>在本地版读取 Codex 学习话题；在手机导入 ChatGPT 学习摘要，调整每日内容。</p></div><button class="btn secondary" data-nav="memory">查看学习记忆 ${icon('arrow')}</button></div></section><section class="panel"><div class="small-title">学习节奏 ${icon('leaf')}</div><div class="setting-row"><div><h4>每天的专注小目标</h4><p>从可以坚持的时长开始。专注计时完成后，才计入目标。</p></div><select id="goal" aria-label="每日专注目标">${[15,25,30,45,60,90,120].map(n=>`<option ${state.settings.goal===n?'selected':''} value="${n}">${n} 分钟</option>`).join('')}</select></div><div class="setting-row"><div><h4>一段专注的时长</h4><p>暂停后继续，完成后自动记录。支持离开页面后返回核算。</p></div><select id="timer-duration" aria-label="专注计时时长">${[15,25,45,50].map(n=>`<option ${timer.duration===n*60?'selected':''} value="${n}">${n} 分钟</option>`).join('')}</select></div></section><section class="panel"><div class="small-title">带着积累，去任何地方 ${icon('download')}</div><div class="setting-row"><div><h4>导出完整备份</h4><p>包含全部 PDF 原文件、阅读进度、笔记、知识点和学习记录。备份保存在你选择的位置。</p></div><button class="btn secondary" data-action="backup">${icon('download')}导出备份</button></div><div class="setting-row"><div><h4>从备份中恢复</h4><p>恢复所选备份的笔记与学习状态，电子书按 ID 合并。请先备份当前数据，避免覆盖新记录。</p></div><button class="btn outline" data-action="restore">${icon('upload')}导入备份</button></div></section><section class="panel"><div class="small-title">继续扩展，你的空间 ${icon('plus')}</div><div class="setting-row"><div><h4>把拾知装进手机</h4><p>添加到主屏幕后，可像普通应用一样打开。初次打开请联网，资源缓存完成后支持离线使用。</p></div><button class="btn secondary" data-action="install">${icon('plus')}安装应用</button></div><div class="setting-row"><div><h4>资源花园</h4><p>查看开源教程，也可以添加其他学科的网址。</p></div><button class="btn outline" data-nav="resources">浏览资源 ${icon('arrow')}</button></div><div class="setting-row"><div><h4>导入 Markdown / 文本</h4><p>把已有的学习材料加入笔记，再用标签整理。每份最多 100 KB。</p></div><button class="btn outline" data-action="import-text">导入材料</button></div><div class="setting-row"><div><h4>公开源码与内容扩展</h4><p>每门课程有独立学科和章节，可继续添加新学科与知识点。公开仓库只包含应用和内置资料。</p></div><a class="btn outline" href="https://github.com/Yang071212/shizhi-study" target="_blank" rel="noopener noreferrer">GitHub ${icon('external')}</a></div></section><section class="panel"><div class="small-title">关于每日更新 ${icon('refresh')}</div><p style="font-size:12px;color:#879879;line-height:2;margin-top:14px">每日学习清单按北京时间 00:00 自动从课程库换一组，离线也可使用。公开版本每天 06:15 检查 GitHub 资源信息并发布，实际时间可能因 GitHub 排队延迟。课程正文随内容版本扩充，当前共 ${LESSONS.length} 节；每日刷新不代表每天新增教材。</p><p style="font-size:11px;color:#a0ab91;line-height:1.9;margin-top:12px">PDF 与个人数据保存在当前设备，不会随公开仓库发布，也不会自动跨设备同步。备份后可手动迁移。首次访问时请等待应用缓存完成；离线能力受浏览器存储策略影响。</p></section><section class="panel"><div class="small-title">开源致谢</div><p style="font-size:11px;color:#8c9a7c;line-height:2;margin-top:12px">PDF 阅读：<a href="https://github.com/mozilla/pdf.js" target="_blank" rel="noopener noreferrer">PDF.js / Apache-2.0</a>；数学公式：<a href="https://github.com/KaTeX/KaTeX" target="_blank" rel="noopener noreferrer">KaTeX / MIT</a>。课程正文为本应用原创整理，外部教程仅提供来源链接。<a href="./THIRD_PARTY_NOTICES.txt" target="_blank" rel="noopener noreferrer">查看许可声明 ↗</a></p></section></div>`;}
function render(){const views={today:todayView,courses:coursesView,knowledge:knowledgeView,books:booksView,notes:notesView,resources:resourcesView,review:reviewView,settings:settingsView,memory:()=>memoryUI.view()};shell(views[route]());updateTimerUI();}
function bindView(){const input=document.querySelector('#page-search');input?.addEventListener('input',e=>{query=e.target.value;const start=e.target.selectionStart;render();const el=document.querySelector('#page-search');el.focus();el.setSelectionRange(start,start);});document.querySelector('#knowledge-mode')?.addEventListener('change',e=>{knowledgeMode=e.target.value;render();});document.querySelector('#goal')?.addEventListener('change',e=>{state.settings.goal=Number(e.target.value);persist();toast('目标已更新，一点点来就好。');});document.querySelector('#timer-duration')?.addEventListener('change',e=>{timer={duration:Number(e.target.value)*60,remaining:Number(e.target.value)*60,end:null};saveTimer();toast('专注时长已更新');});}

function markdown(raw){const tokens=[];const protect=html=>`\u0000${tokens.push(html)-1}\u0000`;let s=String(raw).replace(/(?:```|~~~)([^\n]*)\n([\s\S]*?)(?:```|~~~)/g,(_,lang,code)=>protect(`<pre><code>${esc(code.trimEnd())}</code></pre>`)).replace(/\$\$([\s\S]*?)\$\$/g,(_,math)=>protect(mathHTML(math,true))).replace(/\$([^\n$]+)\$/g,(_,math)=>protect(mathHTML(math,false))).replace(/`([^`\n]+)`/g,(_,code)=>protect(`<code>${esc(code)}</code>`));s=esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');const lines=s.split('\n');let out='',list=false,paragraph=[];const flush=()=>{if(paragraph.length){out+=`<p>${paragraph.join('<br>')}</p>`;paragraph=[];}};for(const line of lines){const h=line.match(/^(#{1,3})\s+(.+)/);const li=line.match(/^\s*[-*]\s+(.+)/);if(!li&&list){out+='</ul>';list=false;}if(h){flush();out+=`<h${Math.min(3,h[1].length+1)}>${h[2]}</h${Math.min(3,h[1].length+1)}>`;}else if(li){flush();if(!list){out+='<ul>';list=true;}out+=`<li>${li[1]}</li>`;}else if(!line.trim()){flush();}else if(/^\u0000\d+\u0000$/.test(line.trim())){flush();out+=line.trim();}else{paragraph.push(line);}}flush();if(list)out+='</ul>';return out.replace(/\u0000(\d+)\u0000/g,(_,i)=>tokens[Number(i)]);}
function mathHTML(math,display){try{return window.katex?window.katex.renderToString(math.trim(),{displayMode:display,throwOnError:false,trust:false,output:'htmlAndMathml'}):`<code>${esc(math)}</code>`;}catch{return `<code>${esc(math)}</code>`;}}
function modal(title,body,footer='',wide=false){closeModal();modalReturnFocus=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal ${wide?'wide':''}" tabindex="-1"><div class="modal-top"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-bottom">${footer}</div>`:''}</section></div>`;document.body.classList.add('no-scroll');document.querySelector('.modal').focus();}
function closeModal(){document.querySelector('#modal-root').innerHTML='';document.body.classList.remove('no-scroll');modalReturnFocus?.focus?.();}
function showLesson(id,review=false){const l=LESSONS.find(x=>x.id===id);if(!l)return;const quiz=l.quiz;modal('拾起一个知识点',`<div class="lesson-meta">${tag(l.subject)}<span>${esc(l.chapter)} · 约 ${l.minutes} 分钟 · ${esc(l.level)}</span></div><h1 class="lesson-title">${esc(l.title)}</h1><p class="lesson-lede">${esc(l.summary)}</p><article class="prose">${markdown(l.content)}</article><section class="takeaways"><h3>把这三点带走</h3><ul>${l.takeaways.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section class="quiz" data-quiz="${id}"><div class="quiz-label">RECALL A LITTLE · 学完试一下</div><h3>${esc(quiz.question)}</h3><div class="quiz-options">${quiz.options.map((opt,i)=>`<button class="quiz-option" data-answer="${i}" data-lesson-id="${id}"><span>${'ABCD'[i]}</span><span>${esc(opt)}</span></button>`).join('')}</div><div class="quiz-feedback hidden" role="status"></div></section>${review?`<div class="review-grades"><button class="btn danger" data-grade="again" data-id="${id}">还不熟 · 明天再看</button><button class="btn secondary" data-grade="good" data-id="${id}">记住了</button><button class="btn" data-grade="easy" data-id="${id}">很轻松</button></div>`:''}`,`<button class="text-btn" data-action="lesson-note" data-id="${id}">${icon('note')}记下自己的理解</button><button class="btn" data-complete="${id}">${icon('check')}学完了，加入复习</button>`,true);}
function answerQuiz(id,index){const l=LESSONS.find(x=>x.id===id);if(!l)return;const correct=index===l.quiz.answer;state.quiz[id]={answer:index,correct,at:Date.now()};if(!correct){state.reviews[id]={due:shiftDay(day(),1),interval:1,streak:0,lastGrade:'again'};}if(!persist())return;const node=document.querySelector(`[data-quiz="${id}"]`);node.querySelectorAll('.quiz-option').forEach((btn,i)=>{btn.classList.toggle('correct',i===l.quiz.answer);btn.classList.toggle('wrong',i===index&&!correct);});const feedback=node.querySelector('.quiz-feedback');feedback.classList.remove('hidden');feedback.textContent=`${correct?'答对了。':'再巩固一下，正确答案是 '+ 'ABCD'[l.quiz.answer]+'。'} ${l.quiz.explanation}${correct?'':' 已安排明天回顾这个知识点。'}`;}
function noteForm(existing=null,knowledge=false,prefill={}){const n=existing||{title:prefill.title||'',body:prefill.body||'',tags:prefill.tags||[...(knowledge?['知识点']:[])]};modal(existing?'编辑这段思考':knowledge?'种下一条新知识':'留下你的思考',`<form id="note-form"><div class="field"><label for="note-title">标题</label><input id="note-title" maxlength="300" required placeholder="给这段思考起个名字" value="${esc(n.title)}"></div><div class="field"><label for="note-tags">标签 · 用逗号分隔，可自由添加新学科</label><input id="note-tags" maxlength="600" placeholder="例如：高数, 极限, 知识点" value="${esc(n.tags.join(', '))}"></div><div class="field"><label for="note-body">正文</label><textarea id="note-body" maxlength="100000" placeholder="用自己的话讲清楚，比抄下答案更有用。">${esc(n.body)}</textarea></div><p class="form-hint">带“知识点”标签的内容会同时出现在知识库。内容自动随完整备份导出。</p><div class="form-actions"><button class="btn secondary" type="button" data-action="close-modal">先放一放</button><button class="btn" type="submit">${icon('check')}保存${knowledge?'知识点':'笔记'}</button></div></form>`);document.querySelector('#note-form').addEventListener('submit',e=>{e.preventDefault();const title=document.querySelector('#note-title').value.trim(),body=document.querySelector('#note-body').value,tags=document.querySelector('#note-tags').value.split(/[,，]/).map(s=>s.trim()).filter(Boolean);if(!title)return;if(tags.length>30||tags.some(t=>t.length>60)){toast('最多 30 个标签，每个标签不超过 60 字');return;}const record={id:existing?.id||crypto.randomUUID(),title,body,tags:[...new Set(tags)],createdAt:existing?.createdAt||Date.now()};if(existing)state.notes=state.notes.map(x=>x.id===existing.id?record:x);else state.notes.push(record);if(persist()){closeModal();render();toast(knowledge?'新知识已种下。':'这段思考，已经留下。');}});}
function showNote(id){const n=state.notes.find(x=>x.id===id);if(!n)return;modal(esc(n.title),`<p class="form-hint">${esc(new Date(n.createdAt).toLocaleString('zh-CN'))} · ${esc(n.tags.map(t=>'#'+t).join(' '))}</p><div class="prose">${markdown(n.body)}</div>`,`<button class="text-btn" data-action="delete-note" data-id="${esc(id)}">${icon('trash')}删除笔记</button><button class="btn secondary" data-action="edit-note" data-id="${esc(id)}">${icon('edit')}继续编辑</button>`);}
function confirmDialog(title,description,action,label='确认'){modal(title,`<p style="line-height:2;color:#839575">${description}</p>`,`<button class="btn secondary" data-action="close-modal">取消</button><button class="btn danger" id="confirm-action">${label}</button>`);document.querySelector('#confirm-action').addEventListener('click',async()=>{try{await action();closeModal();render();}catch(e){toast(e.message);}});}
function resourceForm(){modal('给知识世界，再开一扇窗',`<form id="resource-form"><div class="field"><label for="resource-title">资源名称</label><input id="resource-title" maxlength="300" placeholder="一个课程、教程或网站" required></div><div class="field"><label for="resource-url">完整链接</label><input id="resource-url" type="url" maxlength="2048" placeholder="https://" required></div><div class="field"><label for="resource-category">你的分类</label><input id="resource-category" maxlength="100" placeholder="例如：英语 / 人工智能 / 考研"></div><div class="form-actions"><button class="btn" type="submit">添加资源 ${icon('plus')}</button></div></form>`);document.querySelector('#resource-form').addEventListener('submit',e=>{e.preventDefault();const url=document.querySelector('#resource-url').value.trim();if(safeURL(url)==='#'){toast('请输入完整的 http 或 https 网址');return;}state.customResources.push({id:crypto.randomUUID(),title:document.querySelector('#resource-title').value.trim(),url,category:document.querySelector('#resource-category').value.trim()||'自定义'});if(persist()){closeModal();render();toast('新资源已加入');}});}
function showSearch(){modal('在积累中，找一束光',`<input class="search-modal-input" id="global-search" placeholder="搜索课程、知识点、笔记…" aria-label="搜索全部学习内容"><div class="shortcut-results" id="search-results"><p class="form-hint">试试“循环”“陪域”“行列式”。</p></div>`);const el=document.querySelector('#global-search');el.focus();el.addEventListener('input',()=>{const q=el.value.trim().toLowerCase();const ls=LESSONS.filter(l=>`${l.title} ${l.summary} ${l.content}`.toLowerCase().includes(q)).slice(0,8),ns=state.notes.filter(n=>`${n.title} ${n.body}`.toLowerCase().includes(q)).slice(0,4);document.querySelector('#search-results').innerHTML=q?(ls.map(l=>lessonRow(l)).join('')+ns.map(n=>`<button class="lesson-row" data-note="${esc(n.id)}">${icon('note')}<div class="lesson-info"><h4>${esc(n.title)}</h4><p>个人笔记 · ${esc(n.tags.join(' / '))}</p></div>${icon('chevron')}</button>`).join('')||'<p class="form-hint">暂时没有匹配内容，换一个关键词试试。</p>'):'<p class="form-hint">从一个关键词，找回一段知识。</p>';});}
function chooseFile(accept,multiple=false){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.multiple=multiple;input.hidden=true;document.body.append(input);input.addEventListener('change',()=>{resolve([...input.files]);input.remove();},{once:true});input.addEventListener('cancel',()=>{resolve([]);input.remove();},{once:true});input.click();});}
async function uploadBooks(){const files=await chooseFile('.pdf,application/pdf',true);if(!files.length)return;let count=0;toast('正在把电子书放上书架…');for(const f of files){try{await saveBook(f);count++;}catch(e){toast(`${f.name}：${e.message}`);}}books=await listBooks();if(count){navigate('books');render();toast(`已导入 ${count} 本电子书`);}}
async function readBook(id){try{const b=await getBook(id);if(!b){toast('这本书暂时不在当前设备，请重新导入');return;}openPDF(b,{onProgress:async p=>{await updateBook(id,p);books=await listBooks();},onClose:()=>render()});}catch(e){toast(e.message);}}
async function downloadBackup(){try{toast('正在整理完整备份，大书可能需要稍等…');const blob=await exportBackup(state);const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`拾知完整备份-${day()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);toast('完整备份已生成，请保管好文件');}catch(e){toast(e.message);}}
async function restoreBackup(){confirmDialog('恢复之前，留一份现在的积累。','所选备份将替换当前笔记与学习状态，电子书会按 ID 合并。建议先导出当前备份。',async()=>{closeModal();const [file]=await chooseFile('.json,application/json');if(!file)return;toast('正在检查并恢复备份…');const next=await importBackup(file);state=saveState(next);books=await listBooks();render();toast('备份恢复完成，欢迎带着积累回来。');},'选择备份并恢复');}
async function importText(){const [f]=await chooseFile('.md,.txt,text/plain,text/markdown');if(!f)return;if(f.size>100000){toast('文本请控制在 100 KB 以内');return;}noteForm(null,false,{title:f.name.replace(/\.(md|txt)$/i,''),body:await f.text(),tags:['导入材料']});}
function install(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.finally(()=>{installPrompt=null;});return;}modal('把拾知，放在手机主屏幕',`<p class="lesson-lede">用手机浏览器打开在线地址，然后按以下方式添加。</p><ol class="install-steps"><li><strong>iPhone / iPad：</strong>用 Safari 打开，点分享按钮 → “添加到主屏幕” → “添加”。</li><li><strong>Android：</strong>用 Chrome 或 Edge 打开，在菜单中选择“安装应用”或“添加到主屏幕”。</li><li>首次打开请保持联网，等待离线缓存完成。电子书导入后保存在这台设备。</li></ol><p class="form-hint">不同设备的书籍和记录各自保存，可通过完整备份迁移。</p>`,`<button class="btn" data-action="close-modal">知道了 ${icon('check')}</button>`);}
async function loadResources(manual=false){try{const response=await fetch('./resources.json',{cache:'no-cache'});if(!response.ok)throw new Error();const r=await response.json();if(!Array.isArray(r.items))throw new Error();r.items=r.items.filter(x=>x&&typeof x==='object').map(x=>({...x,stars:typeof x.stars==='number'&&Number.isFinite(x.stars)&&x.stars>0?Math.floor(x.stars):0}));resources=r;if(route==='resources')render();if(manual)toast('已读取最新可用资源快照');}catch{if(resources.status==='loading')resources={items:[],status:'error'};if(manual)toast('暂时无法联网，继续使用已缓存的资源');}}
function saveTimer(){try{sessionStorage.setItem('shizhi-timer',JSON.stringify(timer));}catch{/* The current timer still works when session storage is unavailable. */}}
function updateTimerUI(){let seconds=timer.end?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.remaining;if(timer.end&&seconds<=0){state.sessions.push({date:day(),minutes:timer.duration/60});persist();timer={duration:timer.duration,remaining:timer.duration,end:null};saveTimer();toast('这一段专注完成了，休息一下吧。');if(route==='today')render();return;}document.querySelectorAll('[data-timer]').forEach(el=>el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`);document.querySelectorAll('[data-timer-toggle]').forEach(el=>el.innerHTML=timer.end?`${icon('pause')}暂停一下`:`${icon('play')}${seconds===timer.duration?'开始专注':'继续专注'}`);}
function toggleTimer(){if(timer.end){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.end=null;}else{timer.end=Date.now()+timer.remaining*1000;}saveTimer();updateTimerUI();}
document.addEventListener('click',async e=>{const btn=e.target.closest('button,a');if(!btn)return;try{if(btn.dataset.action?.startsWith('memory-')){await memoryUI.handleAction(btn.dataset.action);return;}if(btn.dataset.nav){navigate(btn.dataset.nav);return;}if(btn.dataset.lesson){showLesson(btn.dataset.lesson,btn.dataset.review==='true');return;}if(btn.dataset.subject){course=btn.dataset.subject;render();window.scrollTo(0,0);return;}if(btn.dataset.filter){filter=btn.dataset.filter;render();return;}if(btn.dataset.book){await readBook(btn.dataset.book);return;}if(btn.dataset.note){showNote(btn.dataset.note);return;}if(btn.dataset.answer!==undefined){answerQuiz(btn.dataset.lessonId,Number(btn.dataset.answer));return;}if(btn.dataset.complete){completeLesson(state,btn.dataset.complete);if(persist()){closeModal();render();toast('知识已拾起，明天再来温习。');}return;}if(btn.dataset.grade){gradeReview(state,btn.dataset.id,btn.dataset.grade);if(persist()){closeModal();render();toast(`已安排 ${state.reviews[btn.dataset.id].due} 再复习`);}return;}switch(btn.dataset.action){case 'search':showSearch();break;case 'close-modal':closeModal();break;case 'back-courses':course=null;render();break;case 'new-note':noteForm();break;case 'new-knowledge':noteForm(null,true);break;case 'edit-note':noteForm(state.notes.find(n=>n.id===btn.dataset.id));break;case 'lesson-note':{const l=LESSONS.find(x=>x.id===btn.dataset.id);noteForm(null,false,{title:l.title+' · 我的理解',body:'',tags:[subject(l.subject).name]});break;}case 'delete-note':confirmDialog('移除这段思考？','删除后无法在应用中撤销。你可以先把它导出备份。',()=>{state.notes=state.notes.filter(n=>n.id!==btn.dataset.id);if(!persist())throw new Error('保存失败');},'删除笔记');break;case 'upload':await uploadBooks();break;case 'delete-book':confirmDialog('从当前设备移除这本书？','电子书与阅读进度将从本机移除。原始 PDF 和已有备份不受影响。',async()=>{await deleteBook(btn.dataset.id);books=await listBooks();},'移除电子书');break;case 'new-resource':resourceForm();break;case 'delete-resource':confirmDialog('移除这个资源？','之后仍可以通过“添加资源”重新加入。',()=>{state.customResources=state.customResources.filter(r=>r.id!==btn.dataset.id);persist();},'移除资源');break;case 'backup':await downloadBackup();break;case 'restore':await restoreBackup();break;case 'import-text':await importText();break;case 'install':install();break;case 'refresh-resources':await loadResources(true);break;case 'timer':toggleTimer();break;case 'timer-reset':timer={duration:timer.duration,remaining:timer.duration,end:null};saveTimer();updateTimerUI();toast('计时已重新准备好');break;}}catch(err){toast(err.message||'暂时未能完成，请再试一次');}});
document.addEventListener('keydown',e=>{if(document.querySelector('.pdf-overlay'))return;if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();showSearch();}if(e.key==='Escape')closeModal();if(e.key==='Tab'&&document.querySelector('.modal')){const items=[...document.querySelectorAll('.modal button,.modal input,.modal textarea,.modal select,.modal a[href]')].filter(x=>!x.disabled);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',onRoute);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('online',()=>{render();loadResources();});window.addEventListener('offline',()=>render());document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(renderedDay!==day()){renderedDay=day();render();}updateTimerUI();}});let renderedDay=day();setInterval(()=>{updateTimerUI();if(renderedDay!==day()){renderedDay=day();render();}},1000);
try{books=await listBooks();}catch{toast('当前浏览器无法保存电子书，建议使用 Safari、Chrome 或 Edge');}onRoute();loadResources();memoryUI.start();if(getStorageWarning())toast(getStorageWarning());
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('发现新版本，下次打开将使用更新后的学习资料');else if(worker.state==='installed')toast('学习空间已缓存，可以离线打开了。');});});}).catch(()=>{});}
